CREATE OR REPLACE FUNCTION public.agri_coverage(f jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path TO public AS $$ WITH r AS (SELECT * FROM public.agri_reports WHERE (COALESCE(f->>'state','')='' OR state=f->>'state') AND (COALESCE(f->>'district','')='' OR district=f->>'district') AND (COALESCE(f->>'market','')='' OR market=f->>'market') AND (COALESCE(f->>'commodity','')='' OR commodity=f->>'commodity') AND (COALESCE(f->>'variety','')='' OR variety=f->>'variety') AND (COALESCE(f->>'source','')='' OR source_name=f->>'source') AND (COALESCE(f->>'start','')='' OR date>=NULLIF(f->>'start','')::date) AND (COALESCE(f->>'end','')='' OR date<=NULLIF(f->>'end','')::date)) SELECT jsonb_build_object('records',count(*),'states',count(DISTINCT state),'districts',count(DISTINCT (state,district)),'markets',count(DISTINCT (state,district,market)),'commodities',count(DISTINCT commodity),'varieties',count(DISTINCT variety),'earliest',min(date),'latest',max(date),'last_update',max(retrieved_at),'missing_prices',count(*) FILTER(WHERE min_price IS NULL OR max_price IS NULL),'missing_arrivals',count(*) FILTER(WHERE arrivals IS NULL),'outliers',count(*) FILTER(WHERE suspicious),'state_coverage',(SELECT COALESCE(jsonb_agg(s),'[]') FROM (SELECT state,count(*) records FROM r GROUP BY state ORDER BY state)s)) FROM r; $$;